style.css:
body {
    background-color: #1a1a1a;
    color: #ffffff;
}

h1, h2, h3 {
    font-family: 'Arial', sans-serif;
    color: #ffcc00;
}

a {
    color: #ffcc00;
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

button {
    background-color: #ffcc00;
    color: #1a1a1a;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
}

button:hover {
    background-color: #e6b800;
}
